#include <stdio.h>



int main(void) {
    int a, n;
    long long term = 0, sum = 0;
    scanf("%d%d", &a, &n);
    for (int i = 0; i < n; i++) { term = term * 10 + a; sum += term; }
    printf("%lld\n", sum);
    return 0;
}
